(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.SpeedDialModel=api})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
const KEY='ob.speedDial.v1',MAX=24;function fail(code){throw Object.assign(new Error(code),{code})}function url(value){if(typeof value!=='string'||value.length>2048||/[\x00-\x20\x7f]/.test(value))fail('INVALID_URL');let u;try{u=new URL(value)}catch(_){fail('INVALID_URL')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password)fail('INVALID_URL');return u.href}
function icon(value){if(value==null)return null;if(!value||!['image/png','image/webp'].includes(value.mime)||typeof value.base64!=='string'||value.base64.length>32768||!/^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value.base64))fail('INVALID_ICON');if(value.mime==='image/png'&&!value.base64.startsWith('iVBORw0KGgo'))fail('INVALID_ICON');if(value.mime==='image/webp'&&!value.base64.startsWith('UklGR'))fail('INVALID_ICON');return {mime:value.mime,base64:value.base64}}
function tile(value){if(!value||typeof value.id!=='string'||!/^[a-zA-Z0-9_-]{1,64}$/.test(value.id)||typeof value.title!=='string'||!value.title.trim()||value.title.length>64)fail('INVALID_TILE');return{id:value.id,title:value.title.trim(),url:url(value.url),icon:icon(value.icon)}}
function validate(value){if(!value||value.version!==1||!Number.isSafeInteger(value.revision)||value.revision<0||!Array.isArray(value.tiles)||value.tiles.length>MAX)fail('INVALID_STORE');const tiles=value.tiles.map(tile);if(new Set(tiles.map(t=>t.id)).size!==tiles.length)fail('DUPLICATE_ID');return{version:1,revision:value.revision,tiles}}
function load(storage){try{const raw=storage.getItem(KEY);if(raw===null)return{version:1,revision:0,tiles:[]};if(raw.length>900000)fail('INVALID_STORE');return validate(JSON.parse(raw))}catch(e){fail(e.code||'STORAGE_UNAVAILABLE')}}
function commit(storage,expected,tiles){const current=load(storage);if(current.revision!==expected)fail('STALE_STATE');const next=validate({version:1,revision:expected+1,tiles});try{storage.setItem(KEY,JSON.stringify(next))}catch(_){fail('STORAGE_FULL')}return next}
function edit(state,input,id){const next=state.tiles.map(t=>({...t})),parsed=tile({...input,id});const i=next.findIndex(t=>t.id===id);if(i<0){if(next.length===MAX)fail('LIMIT_REACHED');next.push(parsed)}else next[i]=parsed;return next}
function move(tiles,id,to){if(!Number.isInteger(to)||to<0||to>=tiles.length)fail('INVALID_POSITION');const next=tiles.slice(),from=next.findIndex(t=>t.id===id);if(from<0)fail('MISSING_TILE');next.splice(to,0,next.splice(from,1)[0]);return next}
return Object.freeze({KEY,MAX,url,icon,tile,validate,load,commit,edit,move});});
